/**
 * The contract `select.tsx` (native) and `select.web.tsx` (radix) both
 * implement. Its own module because Metro resolves `./select` to
 * `select.web.tsx` on web.
 *
 * Narrower than radix's surface. `Group`, `Label`, `Separator` and the two
 * scroll buttons are left out: each would need a native implementation written
 * only so the two halves export the same names, and a sheet has nothing to
 * scroll-button against. Add one when something needs it, on both sides.
 */
import type { ReactNode } from "react";

export type SelectProps = {
  value: string;
  onValueChange: (value: string) => void;
  disabled?: boolean | undefined;
  children: ReactNode;
};

/**
 * The trigger takes the wiring a bound field hands its control, and nothing else.
 *
 * `option-select` was written against `ComponentProps<"button">`, which is every DOM
 * attribute — none of which a `Pressable` honours. This is the subset that means the
 * same thing on both platforms: React Native takes `id` and the `aria-*` props as
 * cross-platform props and react-native-web renders them as the DOM attributes.
 */
export type SelectTriggerProps = {
  id?: string | undefined;
  disabled?: boolean | undefined;
  "aria-labelledby"?: string | undefined;
  "aria-describedby"?: string | undefined;
  "aria-invalid"?: boolean | undefined;
  "aria-required"?: boolean | undefined;
  "aria-label"?: string | undefined;
  className?: string | undefined;
  onBlur?: (() => void) | undefined;
  children: ReactNode;
};

export type SelectValueProps = {
  placeholder?: string | undefined;
  children?: ReactNode;
};

export type SelectContentProps = {
  className?: string | undefined;
  children: ReactNode;
};

export type SelectItemProps = {
  value: string;
  className?: string | undefined;
  children: ReactNode;
};

export type SelectGroupProps = {
  children: ReactNode;
};

export type SelectLabelProps = {
  className?: string | undefined;
  children: ReactNode;
};

export type SelectSeparatorProps = {
  className?: string | undefined;
};

export const SELECT_TRIGGER_CLASS =
  "border-input bg-background h-10 w-full flex-row items-center justify-between rounded-md border px-3 py-2";
export const SELECT_TRIGGER_TEXT_CLASS = "text-foreground text-sm";
export const SELECT_ITEM_CLASS = "w-full flex-row items-center rounded-sm py-1.5 pl-8 pr-2";
export const SELECT_ITEM_TEXT_CLASS = "text-sm text-popover-foreground";
export const SELECT_LABEL_CLASS = "px-2 py-1.5 text-muted-foreground text-xs";
export const SELECT_SEPARATOR_CLASS = "-mx-1 my-1 h-px bg-border";

/**
 * The native select: a trigger that opens the options in a `Modal` sheet.
 *
 * A listbox that drops open under its trigger is a pointer affordance; every
 * native platform shows the choices as a sheet instead, so that is what this
 * renders rather than trying to reproduce radix's anchored popper.
 *
 * `SelectContent` owns the `Modal`, which is why `Select` may hold both a
 * trigger and a content child in any order — the open state lives in the
 * context above them.
 */

import { createContext, useContext, useState } from "react";
import { Modal, Pressable, ScrollView, Text, View } from "react-native";
import { Check, ChevronDown } from "@/components/ui/icons";
import {
  SELECT_ITEM_CLASS,
  SELECT_ITEM_TEXT_CLASS,
  SELECT_LABEL_CLASS,
  SELECT_SEPARATOR_CLASS,
  SELECT_TRIGGER_CLASS,
  SELECT_TRIGGER_TEXT_CLASS,
  type SelectContentProps,
  type SelectGroupProps,
  type SelectItemProps,
  type SelectLabelProps,
  type SelectProps,
  type SelectSeparatorProps,
  type SelectTriggerProps,
  type SelectValueProps,
} from "@/components/ui/select-base";
import { cn } from "@/lib/utils";

type SelectState = {
  disabled: boolean;
  value: string;
  onValueChange: (value: string) => void;
  open: boolean;
  setOpen: (open: boolean) => void;
};

const SelectContext = createContext<SelectState>({
  value: "",
  onValueChange: () => {},
  disabled: false,
  open: false,
  setOpen: () => {},
});

function Select({ value, onValueChange, disabled = false, children }: SelectProps) {
  const [open, setOpen] = useState(false);
  return (
    <SelectContext.Provider
      value={{ value, onValueChange, disabled, open, setOpen: disabled ? () => {} : setOpen }}
    >
      {children}
    </SelectContext.Provider>
  );
}

function SelectTrigger({ className, onBlur, disabled, children, ...aria }: SelectTriggerProps) {
  const select = useContext(SelectContext);
  const isDisabled = disabled ?? select.disabled;
  return (
    <Pressable
      // The `role` is hand-written because a `<button>` has no native counterpart.
      role="button"
      disabled={isDisabled}
      {...aria}
      onPress={() => {
        select.setOpen(true);
        // A native sheet takes focus away from the trigger the way a blur
        // would on web, and a form depends on that to mark the field touched.
        onBlur?.();
      }}
      className={cn(SELECT_TRIGGER_CLASS, isDisabled && "opacity-50", className)}
    >
      {children}
      <ChevronDown className="h-4 w-4 opacity-50" />
    </Pressable>
  );
}

/**
 * Renders whatever the caller passed, or the placeholder when nothing is
 * selected. Bare strings are wrapped for the caller — an unwrapped string
 * inside a `View` throws on native and renders fine on web, which is exactly
 * the kind of divergence a shared primitive should absorb.
 */
function SelectValue({ placeholder, children }: SelectValueProps) {
  const { value } = useContext(SelectContext);
  const content = value && children ? children : placeholder;
  return typeof content === "string" ? (
    <Text className={SELECT_TRIGGER_TEXT_CLASS}>{content}</Text>
  ) : (
    content
  );
}

function SelectContent({ className, children }: SelectContentProps) {
  const { open, setOpen } = useContext(SelectContext);
  return (
    <Modal visible={open} transparent animationType="fade" onRequestClose={() => setOpen(false)}>
      <View className="flex-1 items-center justify-center bg-black/60 p-6">
        {/* Sibling, not parent: `Pressable` has no `stopPropagation`. */}
        <Pressable
          className="absolute inset-0"
          onPress={() => setOpen(false)}
          role="button"
          aria-label="Close"
        />
        <View
          className={cn(
            "max-h-96 w-full max-w-sm rounded-md border border-border bg-popover p-1",
            className,
          )}
        >
          <ScrollView>{children}</ScrollView>
        </View>
      </View>
    </Modal>
  );
}

function SelectItem({ value, className, children }: SelectItemProps) {
  const select = useContext(SelectContext);
  const selected = select.value === value;
  return (
    <Pressable
      role="menuitem"
      onPress={() => {
        select.onValueChange(value);
        select.setOpen(false);
      }}
      className={cn(SELECT_ITEM_CLASS, selected && "bg-accent", className)}
    >
      {selected ? (
        <View className="absolute left-2 h-3.5 w-3.5 items-center justify-center">
          <Check className="h-4 w-4" />
        </View>
      ) : null}
      {typeof children === "string" ? (
        <Text className={SELECT_ITEM_TEXT_CLASS}>{children}</Text>
      ) : (
        children
      )}
    </Pressable>
  );
}

/**
 * A heading and the items under it. Radix builds a real `aria-labelledby` between
 * `SelectPrimitive.Group` and its `Label`; there is no equivalent on native, so the
 * grouping is a `role="group"` container and the label is read as its first child.
 */
function SelectGroup({ children }: SelectGroupProps) {
  return <View role="group">{children}</View>;
}

function SelectLabel({ className, children }: SelectLabelProps) {
  return <Text className={cn(SELECT_LABEL_CLASS, className)}>{children}</Text>;
}

function SelectSeparator({ className }: SelectSeparatorProps) {
  return <View role="separator" className={cn(SELECT_SEPARATOR_CLASS, className)} />;
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

/**
 * The web select: radix, anchored under its trigger. `select.tsx` is the
 * native counterpart and `select-base.ts` holds the contract they share.
 */

import { Select as SelectPrimitive } from "radix-ui";
import { Check, ChevronDown } from "@/components/ui/icons";
import {
  SELECT_ITEM_CLASS,
  SELECT_ITEM_TEXT_CLASS,
  SELECT_LABEL_CLASS,
  SELECT_SEPARATOR_CLASS,
  SELECT_TRIGGER_CLASS,
  SELECT_TRIGGER_TEXT_CLASS,
  type SelectContentProps,
  type SelectGroupProps,
  type SelectItemProps,
  type SelectLabelProps,
  type SelectProps,
  type SelectSeparatorProps,
  type SelectTriggerProps,
  type SelectValueProps,
} from "@/components/ui/select-base";
import { cn } from "@/lib/utils";

function Select({ value, onValueChange, disabled, children }: SelectProps) {
  return (
    <SelectPrimitive.Root
      value={value}
      onValueChange={onValueChange}
      {...(disabled === undefined ? {} : { disabled })}
    >
      {children}
    </SelectPrimitive.Root>
  );
}

function SelectTrigger({ className, onBlur, disabled, children, ...aria }: SelectTriggerProps) {
  return (
    <SelectPrimitive.Trigger
      onBlur={onBlur}
      disabled={disabled}
      {...aria}
      className={cn(
        SELECT_TRIGGER_CLASS,
        SELECT_TRIGGER_TEXT_CLASS,
        "ring-offset-background placeholder:text-muted-foreground focus:ring-ring flex focus:outline-none focus:ring-2 focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50 [&>span]:line-clamp-1",
        className,
      )}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <ChevronDown className="h-4 w-4 opacity-50" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
}

function SelectValue({ placeholder, children }: SelectValueProps) {
  return <SelectPrimitive.Value placeholder={placeholder}>{children}</SelectPrimitive.Value>;
}

function SelectContent({ className, children }: SelectContentProps) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        position="popper"
        className={cn(
          "bg-popover text-popover-foreground data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1 relative z-50 max-h-96 min-w-[8rem] overflow-hidden rounded-md border shadow-md",
          className,
        )}
      >
        <SelectPrimitive.Viewport className="w-full min-w-[var(--radix-select-trigger-width)] p-1">
          {children}
        </SelectPrimitive.Viewport>
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
}

function SelectItem({ value, className, children }: SelectItemProps) {
  return (
    <SelectPrimitive.Item
      value={value}
      className={cn(
        SELECT_ITEM_CLASS,
        SELECT_ITEM_TEXT_CLASS,
        SELECT_LABEL_CLASS,
        SELECT_SEPARATOR_CLASS,
        "focus:bg-accent focus:text-accent-foreground relative flex cursor-default select-none outline-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
    >
      <span className="absolute left-2 flex h-3.5 w-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="h-4 w-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  );
}

function SelectGroup({ children }: SelectGroupProps) {
  return <SelectPrimitive.Group>{children}</SelectPrimitive.Group>;
}

function SelectLabel({ className, children }: SelectLabelProps) {
  return (
    <SelectPrimitive.Label className={cn(SELECT_LABEL_CLASS, className)}>
      {children}
    </SelectPrimitive.Label>
  );
}

function SelectSeparator({ className }: SelectSeparatorProps) {
  return (
    <SelectPrimitive.Separator
      className={cn(SELECT_SEPARATOR_CLASS, "pointer-events-none", className)}
    />
  );
}

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};
